for key,name in [('rice','Long-grain rice'),('risotto-rice','Risotto rice'),('couscous','Couscous'),('orzo','Orzo'),('egg-noodles','Dried egg noodles'),('pearl-barley','Pearl barley'),('spaghetti','Spaghetti'),('plain-flour','Plain flour'),('breadcrumbs','Dried breadcrumbs'),('cornflour','Cornflour'),('cashews','Unsalted cashews'),('peanuts','Unsalted peanuts'),('raisins','Raisins'),('desiccated-coconut','Desiccated coconut')]:food(key,name)
