for key,name in [('chickpeas','Canned chickpeas, drained weight'),('black-beans','Canned black beans, drained weight'),('kidney-beans','Canned kidney beans, drained weight'),('cannellini-beans','Canned cannellini beans, drained weight')]:food(key,name,'g','Cupboard','Use ready-cooked canned beans. Drain and rinse, then weigh the amount shown; buy enough tins to provide that drained weight.')
food('pineapple','Canned pineapple chunks in juice, drained weight','g','Cupboard','Drain, retaining some juice separately if the task asks for it.')
food('sweetcorn','Frozen sweetcorn','g','Frozen','Keep frozen until cooking; follow its packet cooking time.')
food('frozen-peas','Frozen peas','g','Frozen','Keep frozen until cooking; follow its packet cooking time.')
