recipes=[]
SAFE='Check the thickest centre with a clean food thermometer: at least 75°C maintained for 30 seconds. If it is below that, cook longer and check again. The timer is only a reminder.'
def task(title,keys,text,check,tools=None):
 if tools is None:
  tools=[]
  for pattern,label in [(r'\bbowl\b','Mixing bowl'),(r'\bjug\b','Measuring jug'),(r'\bsaucepan\b','Saucepan'),(r'\b(?:frying|wide|deep) pan\b','Large frying pan'),(r'\bsame pan\b','Pan from the previous step'),(r'\boven\b','Oven gloves'),(r'\btray\b','Baking tray'),(r'\bbaking dish\b','Baking dish'),(r'\bthermometer\b','Food thermometer'),(r'\bwhisk','Whisk'),(r'\bstir','Heatproof spoon'),(r'\bgrate','Grater'),(r'\b(?:cut|slice|dice)\b','Knife and stable board')]:
   if re.search(pattern,text,re.I):tools.append(label)
  if not tools:tools=['Clean utensils for the action described']
 return dict(title=title,uses=keys.split(),instructions=text,check=check,skills=[],tools=tools,sourceStage=0)
def add(slug,title,cat,time,items,steps,flavour,source=None,allergens=()):
 ing=[]
 for key,q in items:
  name,unit,aisle,prep=D[key];ing.append([key,name,q,unit,aisle])
 keys=[i[0] for i in ing]
 vegetables=[k for k in keys if D[k][2]=='Fresh produce']
 prept=[]
 if vegetables:prept.append(task('Prepare the vegetables first',' '.join(vegetables),' '.join(D[k][0]+': '+D[k][3] for k in vegetables)+' Prepare these before handling raw meat.','The vegetables are prepared and kept separate from raw meat.',['Non-slip board','Knife','Garlic press or grater where needed']))
 ts=prept+steps
 for n,t in enumerate(ts):t['sourceStage']=n
 r=dict(id=slug,title=title,category=cat,mealType='Dinner',emoji={'Chicken':'🍗','Pork':'🍖','Beef':'🥩'}[cat],theme={'Chicken':'golden','Pork':'peach','Beef':'warm'}[cat],time=time,servings=4,cost=0,description=flavour+' A development recipe with ingredient amounts for four people; use the portion selector to adjust.',tags=[cat,'New to test'],allergens=list(allergens),ingredients=ing,steps=[t['instructions'] for t in ts],beginnerTasks=ts,prep={k:D[k][3] for k in keys},flavour=flavour,family='Serve hot. Use mild versions of sauces if preferred. Larger quantities may need batches and extra time; do not crowd pans. Check product labels and use-by dates.',reviewStatus='Research-informed development recipe — not kitchen-tested by CookTogether',instructionVersion=31,safety={'recipeAllergens':list(allergens),'checkLabels':['Read every sauce, stock, bread and seasoning label; brands and substitutions can change allergens.'],'cooking':SAFE+' Keep raw meat and its utensils separate from ready-to-eat food.'},references=[source] if source else [],reference=source or 'https://www.food.gov.uk/safety-hygiene/cooking-your-food')
 used={k for t in ts for k in t['uses']};assert set(keys)==used,(slug,set(keys)-used,used-set(keys));assert len(keys)==len(set(keys)),slug
 recipes.append(r)
def prepmeat(key,cut):return task('Prepare the meat',key,'On a separate board, '+cut+' Keep it chilled until the pan is ready. Wash hands, knife and board afterwards; do not wash raw meat.','Pieces are the stated size; raw-meat equipment is set aside for cleaning.',['Separate board','Knife'])
def rice():return task('Cook the rice','rice','While the main dish finishes, cook the measured rice in a separate saucepan using the water amount, heat and time on its packet. Start the packet reminder when cooking begins. Drain only if the packet method requires it.','Rice is tender with no hard centre. Serve promptly.',['Saucepan','Measuring jug','Sieve if needed'])
def serve(keys,text):return task('Finish and serve',keys,text,'The food is fully cooked and served hot.',['Clean serving utensils','Plates or bowls'])
