add('pork-sweet-sour-pineapple','Sweet-and-sour pork with pineapple rice','Pork',40,[('pork-tenderloin',600),('peppers',300),('onion',150),('pineapple',250),('vegetable-oil',1),('ketchup',3),('cider-vinegar',3),('soy-sauce',1),('brown-sugar',1),('cornflour',15),('water',180),('rice',280)],[prepmeat('pork-tenderloin','cut pork into 2cm cubes.'),rice(),task('Mix the sauce','ketchup cider-vinegar soy-sauce brown-sugar cornflour water','Mix cornflour with the cold measured water first, then stir in ketchup, vinegar, soy sauce and sugar until smooth.','No dry cornflour lumps remain.',['Jug','Fork']),task('Cook pork and vegetables','pork-tenderloin vegetable-oil peppers onion','Heat oil in a wide pan over medium-high heat. Cook pork for 8–10 minutes, turning regularly, in batches if needed. '+SAFE+' Transfer to a clean plate. Cook onion and peppers in the same pan for 6–8 minutes until softened.','Pork is cooked through and vegetables are tender.'),task('Combine and thicken','pork-tenderloin pineapple','Drain pineapple. Return pork and add pineapple, then stir the prepared sauce again and pour it in. Bubble for 3–4 minutes, stirring, until glossy and hot throughout.','Sauce coats the food and has no chalky taste.'),serve('','Spoon over the cooked rice.')],'Pineapple, vinegar and a glossy tomato sauce give sweet-and-sour contrast.','https://www.bbcgoodfood.com/recipes/sweet-sour-pork',['Soya','Wheat'])
