add('pork-white-bean-braise','Pork and white bean tomato braise','Pork',125,[('pork-shoulder',650),('onion',150),('carrots',200),('garlic',3),('olive-oil',1),('chopped-tomatoes',400),('chicken-stock',350),('cannellini-beans',480),('dried-thyme',1),('bread',200)],[prepmeat('pork-shoulder','cut pork into 3cm cubes.'),brown('pork-shoulder'),task('Make the braising liquid','onion carrots garlic chopped-tomatoes chicken-stock dried-thyme','Lower heat. Cook onion and carrots in the same pan for 8 minutes, stirring. Add garlic for 1 minute, then tomatoes, stock and thyme.','Liquid is simmering.'),task('Braise until tender','pork-shoulder','Return pork and juices, cover and simmer very gently for 75–90 minutes, stirring occasionally. Add a little hot water if drying. '+SAFE+' Keep cooking if the pork still resists a fork.','Pork is cooked through and fork-tender.'),task('Heat beans','cannellini-beans','Drain and rinse beans, stir them into the braise and simmer for 10 minutes until steaming throughout.','Beans are hot and sauce coats the pork.'),serve('bread','Serve in bowls with sliced bread for the sauce.')],'Tender pork and creamy white beans in a herby tomato sauce.',None,['Wheat','Celery (stock)'])
add('bacon-leek-creamy-spaghetti','Bacon and leek spaghetti','Pork',35,[('bacon',250),('leeks',300),('garlic',2),('spaghetti',320),('olive-oil',1),('double-cream',150),('parmesan',50),('frozen-peas',200)],[task('Cook pasta and peas','spaghetti frozen-peas','Cook spaghetti in boiling water following its packet. Add frozen peas for their full packet cooking time before the pasta is due to finish. Reserve a mug of cooking water using a heatproof jug, then drain.','Pasta is tender and peas have cooked for the required time.'),task('Cook bacon','bacon olive-oil','Use kitchen scissors or a separate board to cut bacon into short strips. Heat oil in a wide frying pan over medium heat and cook bacon for 6–10 minutes, stirring, until thoroughly cooked and steaming hot. Wash equipment after handling raw bacon.','Bacon is cooked through.'),task('Soften leeks','leeks garlic','Add leeks to the bacon pan and cook over medium-low heat for 8 minutes, stirring. Add garlic for the final minute.','Leeks are soft, not browned hard.'),task('Make the sauce','double-cream parmesan','Add cream and simmer gently for 2 minutes. Finely grate Parmesan, turn off heat and stir it into the sauce.','Cheese is melted into the cream.'),serve('','Toss drained pasta and peas through the sauce. Add reserved pasta water a small splash at a time until the sauce coats the strands. Serve immediately.')],'Sweet leeks and smoky bacon make a creamy pasta sauce without raw egg.',None,['Wheat','Milk'])
