add('pork-cabbage-rice-pan','Pork, cabbage and caraway rice pan','Pork',45,[('pork-mince',600),('cabbage',350),('onion',150),('garlic',2),('olive-oil',1),('caraway',1),('sweet-paprika',1),('chopped-tomatoes',400),('chicken-stock',150),('rice',280),('sour-cream',100)],[rice(),task('Brown the pork','pork-mince olive-oil','Heat oil in a deep frying pan over medium-high heat. Add pork mince, break into small clumps and cook for 8–10 minutes, stirring.','Mince is separated and beginning to brown.'),task('Soften cabbage and onion','cabbage onion garlic caraway sweet-paprika','Add onion and cabbage. Cook over medium heat for 8 minutes, stirring. Add garlic, caraway and paprika for the final minute.','Cabbage is softening.'),task('Simmer','pork-mince chopped-tomatoes chicken-stock','Stir in tomatoes and stock. Cover and simmer gently for 15 minutes, stirring occasionally. '+SAFE,'Pork is cooked through and cabbage is tender.'),serve('sour-cream','Serve over rice with sour cream spooned onto each portion.')],'Caraway and sweet paprika give this cabbage pan a distinctive warm flavour.',None,['Milk','Celery (stock)'])
