# BEEF — long braises use braising steak, never quick-fry strips.
def beefbraise(slug,title,extras,liquid,flavour,finish,side='rice',source=None):
 items=[('diced-beef',650),('onion',180),('garlic',3),('olive-oil',1)]+extras+liquid+([('rice',280)] if side=='rice' else [('bread',200)])
 arom=[k for k,q in extras];liq=[k for k,q in liquid]
 steps=[prepmeat('diced-beef','cut braising steak into 3cm cubes.'),brown('diced-beef'),task('Build the braising base','onion garlic '+' '.join(arom),'Lower heat to medium. Soften onion in the same pan for 7 minutes, stirring. Add garlic and all the other ingredients listed for this task. Stir over medium-low heat for 2 minutes; lower heat if spices catch.','Onion is softened and the base smells fragrant.'),task('Braise gently','diced-beef '+' '.join(liq),'Return beef and its juices. Add the liquid ingredients listed here and stir. Bring to a gentle simmer, cover and cook on very low heat for 2–2½ hours, stirring occasionally. Add a little hot water if the base begins to dry. '+SAFE+' Continue cooking if a fork does not pass easily into the meat.','Beef is fully cooked and fork-tender.')]
 if side=='rice':steps.append(rice())
 steps.append(serve('' if side=='rice' else 'bread',finish+(' Serve over rice.' if side=='rice' else ' Serve with sliced bread.')))
 add(slug,title,'Beef',190,items,steps,flavour,source)
